# Local frozen transaction replay and separately observed specialist servicing.
if(!exists('register_rating_model_version'))library(creditratingsystem)
.specialized_ref<-function(source,identity,...){list('$ref'=list(source=source,id=identity,path=list(...)))}
.specialized_governance_journey<-function(j,model,later_model,verify,return_audit_artifacts=FALSE){
 sid<-j$case_id;origin<-'2023-01-01';aid<-paste0(sid,'-assessment');target<-j$simulation_target;facts<-list(product=j$product,variant=j$variant,legal_verified=TRUE)
 rules<-list(list(rule_id=sid,profile_id=sid,profile_version='1',priority=1,effective_from=origin,effective_to=NULL,known_at=origin,conditions=lapply(names(facts),function(k)list(field=k,operator='eq',value=facts[[k]]))))
 applicability<-list(contract_id=sid,version='1',required_features=as.list(names(facts)),allowed_values=lapply(facts,function(v)list(v)),support_bounds=setNames(list(),character()),maximum_age_days=setNames(rep(list(90L),length(facts)),names(facts)))
 pdpath<-list('transactions',0L,'risk','pd');elpath<-list('transactions',0L,'risk','expected_loss');targetpath<-list('transactions',0L,'risk','target')
 step<-list(step_id='transaction',method_id='simulation.simulate_transactions',arguments=setNames(lapply(names(j$frozen_arguments),function(k).specialized_ref('artifact',k)),names(j$frozen_arguments)),argument_types=setNames(list(),character()),output_contract=list(shape='object',unit='transaction_paths',target=NULL,fields=list(list(path=pdpath,unit='probability',target=target,target_path=targetpath),list(path=elpath,unit='EUR',target=target,target_path=targetpath))))
 fields<-list('risk.pd'=list(type='number'),'affordability.status'=list(type='category',values=list('AFFORDABLE','NOT_AFFORDABLE')),'eligibility.status'=list(type='category',values=list('ELIGIBLE','INELIGIBLE')),'operations.status'=list(type='category',values=list('CLEAR','HOLD')))
 policy_spec<-list(schema_version='1.1',policy_id=paste0(sid,'-policy'),version='1',approval_reference='Synthetic local credit review',known_at=origin,effective_from=origin,effective_until='2024-01-01',default_action='REFER',missing_action='BLOCKED',target=target,fields=fields,approval_contract=list(domain='WHOLESALE_CREDIT',affordability=list(mode='REQUIRED'),required_gates=list(list(field='affordability.status',value='AFFORDABLE'),list(field='eligibility.status',value='ELIGIBLE'),list(field='operations.status',value='CLEAR'))),rules=list(list(rule_id='bounded-risk',priority=1,action='APPROVE',reason_code='RISK_AND_DOCUMENTED_GATES',when=list(list(field='risk.pd',op='le',value=.11)))))
 policy<-compile_credit_decision_policy(policy_spec)$value;gate<-j$origination_gate
 pdref<-do.call(.specialized_ref,c(list('step','transaction','value'),pdpath));elref<-do.call(.specialized_ref,c(list('step','transaction','value'),elpath))
 decision<-list(policy=.specialized_ref('artifact','credit_policy'),risk=list(as_of=origin,known_at=origin,pd=pdref,target=target,freshness='CURRENT'),affordability=list(as_of=origin,known_at=origin,status=if(gate$available_cashflow>=gate$debt_service)'AFFORDABLE'else'NOT_AFFORDABLE'),eligibility=list(as_of=origin,known_at=origin,status=if(gate$legal_verified)'ELIGIBLE'else'INELIGIBLE'),operations=list(as_of=origin,known_at=origin,status=gate$operations),as_of=origin,known_at=origin)
 components<-list(list(component_id='pd',quantity='PD',value=pdref,subject_id=sid,subject_type='obligor',variant='cash_pool',definition=target),list(component_id='el',quantity='EL',value=elref,subject_id=sid,subject_type='obligor',variant='before_payment_guarantee',definition=target,currency='EUR'))
 transitions<-list(list(from_state='DRAFT',to_state='REVIEWED',event_type='review',required_gates=list('checked')),list(from_state='REVIEWED',to_state='FINAL',event_type='finalize',required_gates=list('approved')),list(from_state='FINAL',to_state='SUPERSEDED',event_type='exit',required_gates=list('settled')))
 recipe<-list(method='assessment_pipeline',version='2.0',parameters=list(routing_rules=rules,applicability_contract=applicability,steps=list(step),components=components,effects=list(),transitions=transitions,event_dependencies=list(list(assessment_id=aid,dependency_type='subject',dependency_id=sid)),decision=decision))
 artifacts<-setNames(lapply(names(j$frozen_arguments),function(k)list(kind=if(k=='entity_innovations')'innovations'else'parameters',content=j$frozen_arguments[[k]],sha256=content_fingerprint(j$frozen_arguments[[k]])$value,known_at=origin)),names(j$frozen_arguments))
 artifacts$credit_policy<-list(kind='parameters',content=policy,sha256=content_fingerprint(policy)$value,known_at=origin)
 bundle<-list(model=model,dependencies=list(artifacts=artifacts),configuration=list(assessment_recipe=recipe));registration<-list(model_id=model$model_id,model_version=model$model_version,registered_at=origin)
 registry<-register_rating_model_version(NULL,bundle,registration)$value;digest<-registry$entries[[1]]$model_hash
 assignment<-list(assignment_id=paste0(sid,'-champion'),profile_id=sid,purpose='CASHFLOW_SIMULATION',model_id=model$model_id,model_version='1',model_hash=digest,effective_from=origin,effective_to=NULL,known_at=origin)
 selected<-select_effective_model(registry,list(assignment),sid,'CASHFLOW_SIMULATION',origin,origin)$value
 attributes<-lapply(facts,function(v)list(value=v,observed_at=origin,known_at=origin))
 subjects<-build_rating_subjects(list(obligor=list(list(subject_id=sid,version='1',attributes=attributes,effective_from=origin,effective_to=NULL,known_at=origin))),list(),origin,origin)$value
 request<-list(row_id='origination',known_at='2023-01-02',model_id=model$model_id,model_version='1',model_hash=digest,recipe=recipe,input=list(snapshot=list(subject_id=sid,subject_type='obligor',as_of=origin,known_at=origin,attributes=attributes),datasets=setNames(list(),character()),assessment_id=aid,assessment_known_at=origin,calculated_at='2023-01-02',lifecycle_events=list(),events=list()))
 original<-rate_subject_batch(list(request),registry,paste0(sid,'-origination'),'2023-01-02')$value$rows[[1]]
 if(original$status!='OK')stop(paste(original$error_code,original$message))
 observation<-j$observed;history<-request;history$row_id<-'closed-history';history$known_at<-observation$closure_known_at
 history$input$lifecycle_events<-list(list(event_id='review',type='review',occurred_at='2023-01-03',known_at='2023-01-03',reason='Cashflow, rights and legal pooling reviewed',gates=list(checked=TRUE)),list(event_id='final',type='finalize',occurred_at='2023-01-04',known_at='2023-01-04',reason='Local approval; separate funding instruction required',gates=list(approved=TRUE)),list(event_id='exit',type='exit',occurred_at=observation$closure_at,known_at=observation$closure_known_at,reason=observation$exit_reason,gates=list(settled=TRUE)))
 event<-function(identity,occurred,known,payload)list(event_id=identity,revision='1',occurred_at=occurred,known_at=known,dependencies=list(list(type='subject',id=sid)),payload=payload)
 missed<-event('missed-coupon',observation$scheduled_due_date,observation$early_warning_at,list(scheduled_due=observation$scheduled_due,received=observation$received,source=observation$source))
 history$input$events<-list(missed,missed,event('delinquency',observation$delinquency_at,observation$delinquency_at,list(days_past_due=observation$delinquency_days,not_yet_default=TRUE)),event('restructuring-proposal',observation$proposal_at,observation$proposal_at,list(proposal_only=TRUE,contract_changed=FALSE)),event('observed-default',observation$default_at,observation$default_known_at,list(material_days_past_due=observation$default_days_past_due,default_observed=TRUE)))
 closed<-rate_subject_batch(list(history),registry,paste0(sid,'-closed'),history$known_at)$value$rows[[1]];stopifnot(closed$status=='OK')
 replay<-replay_assessment_history(list(request,history),registry,list(original,closed),'2025-02-01')$value
 later_bundle<-bundle;later_bundle$model<-later_model;later_registry<-register_rating_model_version(registry,later_bundle,list(model_id=model$model_id,model_version='2',registered_at='2024-01-03'))$value
 later_replay<-replay_assessment_history(list(request,history),later_registry,list(original,closed),'2025-02-01')$value
 tampered<-closed;tampered$event_state_hash<-'tampered';rejected<-replay_assessment_history(list(history),registry,list(tampered),'2025-02-01')$value
 assessment<-original$value$assessment;pd_component<-Filter(function(c)c$component_id=='pd',assessment$components)[[1]];el_component<-Filter(function(c)c$component_id=='el',assessment$components)[[1]];freshness<-list(maximum_age_days=90,maximum_information_age_days=90,trigger_types=list('missed_payment'))
 current<-check_assessment_freshness(assessment,freshness,list(),'2023-02-01','2023-02-01')$value
 trigger<-list(event_id='missed',subject_id=sid,type='missed_payment',occurred_at='2024-01-01',known_at='2024-01-02');stale<-check_assessment_freshness(assessment,freshness,list(trigger),'2024-01-02','2024-01-02')$value
 if(verify){stopifnot(replay$status=='REPRODUCED',later_replay$status=='REPRODUCED',rejected$status=='NOT_REPRODUCIBLE',original$value$decision$action=='APPROVE',closed$value$assessment$state=='SUPERSEDED',identical(vapply(closed$value$event_trace,function(x)x$status,character(1)),c('APPLIED','DUPLICATE','APPLIED','APPLIED','APPLIED')),abs(pd_component$value-j$reference_pd)<1e-12,abs(el_component$value-j$reference_el)<1e-12,current$status=='CURRENT',stale$status=='STALE')}
 report<-list(product=j$product,variant=j$variant,subject_count=length(subjects$subjects),selection=selected$status,decision=original$value$decision$action,initial_state=assessment$state,final_state=closed$value$assessment$state,current=current$status,stale=stale$status,event_statuses=lapply(closed$value$event_trace,function(x)x$status),pd=pd_component$value,expected_loss=el_component$value,original_result_hash=original$result_hash,historical_result_hash=closed$result_hash,replay=replay$status,replay_after_later_fit=later_replay$status,tampered_replay=rejected$status,observed_servicing=observation)
 if(return_audit_artifacts)list(report=report,registry=registry,requests=list(request,history),results=list(original,closed))else report
}
run_specialized_governance<-function(data=NULL,verify_reference=TRUE,model_path=NULL,return_audit_artifacts=FALSE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/specialized_governance.json',package='creditratingsystem'),simplifyVector=FALSE)
 if(is.null(model_path))model_path<-system.file(paste0('extdata/',data$model_resource),package='creditratingsystem')
 model<-load_fitted_model(model_path)$value
 history<-data$macro_history;history$dates<-c(history$dates,list('2024-01-01'));history$release_dates<-c(history$release_dates,list(list('2024-01-01')));history$values<-c(history$values,list(list(.5)))
 training<-data$macro_training;training$end<-'2024-01-01';training$known_at<-'2024-01-01';training$split_id<-'later_macro_2016_2024'
 later<-fit_var(history,lags=1,training=training,target=data$macro_target,model_id=model$model_id,model_version='2',covariance_estimator='mle')$model
 list(data_origin='SYNTHETIC',frozen_generation_model_hash=content_fingerprint(model)$value,scope='Local transaction generation provenance, frozen simulation and observed servicing; no validation labels from simulated paths.',journeys=setNames(lapply(data$journeys,function(j).specialized_governance_journey(j,model,later,verify_reference,return_audit_artifacts)),vapply(data$journeys,function(j)j$case_id,character(1))))
}
